  "Tine width": "Larghezza denti",
  "Tine height": "Altezza denti",
  "Tine spacing": "Passo denti",
  "Tine count": "Numero denti",
  "Base width": "Larghezza base",
  "Base height": "Altezza base",
  "Base flare": "Svasatura base",
  "Chamfer size": "Dimensione smusso",
  "Sway brace angle": "Angolo controvento",
  "Sway brace width": "Larghezza controvento",
